def summary_ranges(nums):
    result = []
    start = 0
    while start < len(nums):
        stop = start
        while stop + 1 < len(nums) and nums[stop + 1] == nums[stop] + 1:
            stop += 1
        if start == stop:
            result.append(str(nums[start]))
        else:
            result.append(str(nums[start]) + "->" + str(nums[stop]))
        start = stop + 1
    return result

